<?php require __DIR__.'/includes/core.php';$u=require_login();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=one('SELECT password_hash FROM users WHERE id=?',[$u['id']]);if(!password_verify($_POST['old']??'',$old['password_hash']))$error='Current password incorrect.';elseif(strlen($_POST['new']??'')<12)$error='New password must have at least 12 characters.';else{sql('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?',[password_hash($_POST['new'],PASSWORD_DEFAULT),$u['id']]);flash('Password changed.');go(dashboard_path($u['role']));}}ob_start();if($error)echo '<div class="alert error">'.h($error).'</div>';?><div class="card"><form method="post"><?=token()?><label>Current password</label><input type="password" name="old" required><label>New password (12+ characters)</label><input type="password" name="new" minlength="12" required><p><button>Update password</button></p></form></div><?php layout('Change password',ob_get_clean());